  console.log('1: Start');
  const p = new Promise(resolve => {
    setTimeout(() => resolve('3: Promise resolved!'), 500);
  });
  console.log('2: Waiting...');
  const res = await p;
  console.log(res);
  console.log('4: Done');
}
demoAsync();

