function Greeting({ name }) {
  const [liked, setLiked] = React.useState(false);
  return (
    <div>
      <h3>Hello, {name}!</h3>
      <button onClick={() => setLiked(!liked)}>
        {liked ? '❤️ Liked' : '🤍 Like'}
      </button>
    </div>
  );
}`;
console.log('Component definition ready!');

